def run(ctx, args):
    """Quick probe that checks current best score and suggests hexagonal packing."""
    best = ctx.best_score()
    remaining = ctx.budget_left().get("budget_left", 0)

    result = {"best_score": best, "budget_left": remaining}

    # Suggest hexagonal packing when budget is available
    if remaining > 5 and best < 2.6:
        result["suggestion"] = "Switch to hexagonal packing: use staggered rows with vertical spacing ~1.732r, place large central circle, pack shells around it."
        result["target"] = 2.635

    return result
